impl<T> Queue<T> {
    fn new() -> Self { Queue { items: VecDeque::new() } }
    fn enqueue(&mut self, item: T) { self.items.push_back(item); }
    fn dequeue(&mut self) -> Option<T> { self.items.pop_front() }
