type Link<T> = Option<Box<BSTNode<T>>>;

struct BSTNode<T: Ord> {
    val: T,
    left: Link<T>,
    right: Link<T>,
}

impl<T: Ord> BSTNode<T> {
    fn new(val: T) -> Self { BSTNode { val, left: None, right: None } }
    fn insert(&mut self, val: T) {
        match val.cmp(&self.val) {
            std::cmp::Ordering::Less => match self.left {
                Some(ref mut left) => left.insert(val),
                None => self.left = Some(Box::new(BSTNode::new(val))),
            },
            _ => match self.right {
                Some(ref mut right) => right.insert(val),
                None => self.right = Some(Box::new(BSTNode::new(val))),
            },
        }
    }
    fn contains(&self, val: &T) -> bool {
        match val.cmp(&self.val) {
            std::cmp::Ordering::Equal => true,
            std::cmp::Ordering::Less => self.left.as_ref().map_or(false, |n| n.contains(val)),
            std::cmp::Ordering::Greater => self.right.as_ref().map_or(false, |n| n.contains(val)),
        }
    }
}

use std::collections::HashSet;

fn dfs(graph: &[Vec<usize>], start: usize) -> Vec<usize> {
    let mut visited = HashSet::new();
    let mut stack = vec![start];
    let mut result = Vec::new();
    while let Some(node) = stack.pop() {
        if visited.insert(node) {
            result.push(node);
            for &neighbor in graph[node].iter().rev() {
                if !visited.contains(&neighbor) {
                    stack.push(neighbor);
                }
            }
        }
    }
    result
}

use std::collections::{HashSet, VecDeque};

fn bfs(graph: &[Vec<usize>], start: usize) -> Vec<usize> {
    let mut visited = HashSet::new();
    visited.insert(start);
    let mut queue = VecDeque::new();
    queue.push_back(start);
    let mut result = Vec::new();
    while let Some(node) = queue.pop_front() {
        result.push(node);
        for &neighbor in &graph[node] {
            if visited.insert(neighbor) {
                queue.push_back(neighbor);
            }
        }
    }
    result
}

